mapper.update:
UPDATE tc_user_group_permission
   SET granted_at = CURRENT_TIMESTAMP,
       granted_by = #{p.grantedBy}
 WHERE group_id = #{p.groupId}
   AND perm_id = #{p.permId}

mapper.select:
SELECT 
  FROM tc_user_group_permission
 WHERE group_id = #{groupId}
   AND perm_id = #{permId}

SELECT 
  FROM tc_user_group_permission
 WHERE group_id = #{groupId}
 ORDER BY perm_id ASC
 LIMIT #{limit} OFFSET #{offset}

mapper.delete:
